pub fn get_or_insert(&mut self, key: &str, compute: impl FnOnce() -> String) -> &String {
    if let Some(found) = self.entries.get(key) {
        return found;
    }
    let value = compute();
    self.entries.insert(key.to_string(), value);
    self.entries.get(key).unwrap()
}

pub fn get_or_insert(&mut self, key: &str, compute: impl FnOnce() -> String) -> &String {
    self.entries.entry(key.to_string()).or_insert_with(compute)
}

pub fn get_or<'a>(&'a self, key: &str, default: &'a str) -> &'a str {
    self.entries.get(key).map(String::as_str).unwrap_or(default)
}

use std::borrow::Cow;

pub fn get_or<'a>(&'a self, key: &str, default: Cow<'a, str>) -> Cow<'a, str> {
    match self.entries.get(key) {
        Some(found) => Cow::Borrowed(found.as_str()),
        None => default,
    }
}
